####### DE analysis  ########
dir.create("../deseq2")
setwd("../deseq2")
design(dds) = ~Sample
dds = DESeq(dds)
res  = results(dds, contrast = c("Sample", "polyic","control"))
write.csv(res,file = "DEanalysis.csv")

# Get DEGs
up.lst <- row.names(res[!is.na(res$log2FoldChange) & !is.na(res$padj) & res$log2FoldChange > 0 & res$padj < 0.05,])
dn.lst <- row.names(res[!is.na(res$log2FoldChange) & !is.na(res$padj) & res$log2FoldChange < 0 & res$padj < 0.05,])
length(up.lst)
length(dn.lst)
write.table(sub(":.*$","",up.lst), file="DEGs_Up.ENSEMBL_ID.txt", row.names = FALSE, col.names = FALSE, sep = "\t", quote = FALSE)
write.table(sub(":.*$","",dn.lst), file="DEGs_Down.ENSEMBL_ID.txt", row.names = FALSE, col.names = FALSE, sep = "\t", quote = FALSE)
# Sort by p-value
res.srt = res[order(res$pvalue),]
write.csv(res.srt, file = "DE_sorted.csv")
write.csv(res[!is.na(res$log2FoldChange) & !is.na(res$padj) & res$log2FoldChange > 0 & res$padj < 0.05,], file = "DEGs_Up_sorted.csv")
write.csv(res[!is.na(res$log2FoldChange) & !is.na(res$padj) & res$log2FoldChange < 0 & res$padj < 0.05,], file = "DEGs_down_sorted.csv")
de.lst = unique(c(up.lst,dn.lst))

# MA-plot
tiff(file="MA.tiff",width=20,height = 20,units = "cm", compression = "lzw",bg="white",res=600)
par(mar=c(4,4,1,1), mfrow=c(1,1))
plot(
  log10(res$baseMean+1), res$log2FoldChange, xlab="Average read counts", ylab="log2fold(polyic/NC)",
  cex=.1, pch=19, col=alpha('grey',1), xaxt = "n", xlim=c(0,6), ylim=c(-10,15)
)
axis(1, at = 0:6, labels = 10^(0:6))
abline(h=0, lwd=3, col=alpha('#8B0000',1))
points(log10(res$baseMean[row.names(res) %in% up.lst]+1), res$log2FoldChange[row.names(res) %in% up.lst], cex=0.5, pch=19, col='#8B0000')
points(log10(res$baseMean[row.names(res) %in% dn.lst]+1), res$log2FoldChange[row.names(res) %in% dn.lst], cex=0.5, pch=19, col='#228B22')
dev.off()

pdf(file="MA.pdf",width=5,height = 5)
