  cex=.1, pch=19, col=alpha('grey',0.5), xaxt = "n", xlim=c(0,6), ylim=c(-10,15)
)
axis(1, at = 0:6, labels = 10^(0:6))
abline(h=0, lwd=3, col=alpha('#FFB3B3',0.5))
points(log10(res$baseMean[row.names(res) %in% up.lst]+1), res$log2FoldChange[row.names(res) %in% up.lst], cex=0.3, pch=19, col='#FFB3B3')
points(log10(res$baseMean[row.names(res) %in% dn.lst]+1), res$log2FoldChange[row.names(res) %in% dn.lst], cex=0.3, pch=19, col='#B3FFB3')
dev.off()

## difgene_pheatmap
data_cpm <- log2(cpm(data)+1)
res.srt <- na.omit(res.srt)
res.srt$regulated <- "normal"
loc_up <- intersect(which(res.srt$log2FoldChange > 0),which(res.srt$padj < 0.05))
loc_down <- intersect(which(res.srt$log2FoldChange < 0),which(res.srt$padj < 0.05))
res.srt$regulated[loc_up] <- "up"
res.srt$regulated[loc_down] <- "down"
DEGSeq2_sigGene <- rownames(res.srt)[res.srt$regulated!="normal"]
DEGSeq2_sig <- res.srt[res.srt$regulated!="normal",]
dat1 <- data.frame(data_cpm[match(DEGSeq2_sigGene,rownames(data_cpm)),])
res.srt_1 <- as.data.frame(res.srt)
dat1$log2fc <- res.srt_1[match(rownames(dat1),rownames(res.srt_1)),]$log2FoldChange
write.csv(dat1, file = "DEGs_trna.csv")
dat2 <- dat1[,1:4]
P <- pheatmap(dat2,
         show_rownames = T,
         show_colnames = T,
         cluster_cols = F,
         cluster_rows=T,
         filename='de_pheatmap.tiff',
         fontsize_row=15, 
         fontsize_col=15,
         height=30,  
         width =6,
         scale = "row",
         angle_col=45, 
         color =colorRampPalette(c("#B3B3FF", "#E0E0E0","#FFB3B3"))(100),
         clustering_distance_rows = 'euclidean',
         clustering_method = 'single',
         cellwidth = 25,
         cellheight = 25
)
pheatmap(dat2,
         show_rownames = T,
         show_colnames = T,
         cluster_cols = F,
         cluster_rows=T,
         filename='de_pheatmap.pdf',
         fontsize_row=15, 
         fontsize_col=15,
         height=15,  
         width =6,
         scale = "row",
         angle_col=45, 
         color =colorRampPalette(c("#B3B3FF", "#E0E0E0","#FFB3B3"))(100),
         clustering_distance_rows = 'euclidean',
         clustering_method = 'single',
         cellwidth = 25,
         cellheight = 25
)
